package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"strconv"
	"sync"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

// GenerateRequest represents a request to generate an ID
type GenerateRequest struct {
	Type      string `json:"type"`
	MsgID     int64  `json:"msg_id"`
}

// GenerateResponse represents the response with a generated ID
type GenerateResponse struct {
	Type       string `json:"type"`
	InReplyTo  int64  `json:"in_reply_to,omitempty"`
	ID         string `json:"id"`
}

func main() {
	node, err := maelstrom.NewNode(os.Stdin, os.Stdout)
	if err != nil {
		log.Fatal(err)
	}

	node.Handle("init", func(ctx *maelstrom.Context, req maelstrom.Req) {
		var m struct {
			ID string `json:"id"`
		}
		if err := json.Unmarshal([]byte(req.Body), &m); err != nil {
			log.Printf("failed to unmarshal init: %v", err)
			return
		}

		// Store the node's ID for use in generating unique IDs
		nodeID := m.ID
		ctx.Reply(req.Src, generateOK(nodeID))
	})

	node.Handle("generate", func(ctx *maelstrom.Context, req maelstrom.Req) {
		var r GenerateRequest
		if err := json.Unmarshal([]byte(req.Body), &r); err != nil {
			log.Printf("failed to unmarshal generate: %v", err)
			return
		}

		// Store the node's ID and use it to generate unique IDs
		var nodeID string
		ctx.Ready() // Wait for init before replying
		if id, ok := ctx.Store().Get("node-id"); !ok {
			nodeID = "unknown"
		} else {
			nodeID = id.(string)
		}

		// Generate a unique ID: nodeID-counter format ensures uniqueness across nodes
		counter, _ := strconv.Atoi(nodeID[strings.LastIndex(nodeID, "-")+1:])

		ctx.Store().Set("counter", counter+1)

		id := fmt.Sprintf("%s-%d", nodeID, counter+1)
		fmt.Printf("[%s] generating id %s\n", nodeID, id)

		ctx.Reply(req.Src, generateOK(nodeID, counter+1))
	})

	node.Run()
}

func generateOK(nodeID string) maelstrom.Resp {
	return map[string]interface{}{
		"type":       "generate_ok",
		"in_reply_to": 0,
		"id":         fmt.Sprintf("%s-0", nodeID),
	}
}

package main

import (
	"context"
	"encoding/json"
	"log"
	"os"
	"strconv"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

func main() {
	ctx := context.Background()
	node, err := maelstrom.NewNode(ctx, os.Stdin, os.Stdout)
	if err != nil {
		log.Fatal(err)
	}

	node.Handle("init", func(ctx *maelstrom.Context, req maelstrom.Req) {
		var m struct {
			ID string `json:"id"`
		}
		if err := json.Unmarshal([]byte(req.Body), &m); err != nil {
			log.Printf("failed to unmarshal init: %v", err)
			return
		}

		nodeID := m.ID
		ctx.Reply(req.Src, generateOK(nodeID))
	})

	node.Handle("generate", func(ctx *maelstrom.Context, req maelstrom.Req) {
		var r struct {
			Type      string `json:"type"`
			MsgID     int64  `json:"msg_id"`
			ReqID     string `json:"req_id,omitempty"`
		}
		if err := json.Unmarshal([]byte(req.Body), &r); err != nil {
			log.Printf("failed to unmarshal generate: %v", err)
			return
		}

		var nodeID string
		ctx.Ready() // Wait for init before replying
		id, ok := ctx.Store().Get("node-id")
		if !ok {
			nodeID = "unknown"
		} else {
			nodeID = id.(string)
		}

		// Parse the node ID suffix (e.g., "1" from "n1", or "123" from "n123")
		suffix := ""
		for i := len(nodeID) - 1; i >= 0; i-- {
			if c := nodeID[i]; c >= '0' && c <= '9' {
				suffix += string(c)
			} else {
				break
			}
		}

		// Convert to int for ordering, default to 999 if parsing fails or empty
		seqNum, _ := strconv.Atoi(suffix)
		if seqNum == 0 {
			seqNum = 999
		}

		// Get and increment the counter stored atomically in the context store
		counter, err := ctx.Store().Get("counter")
		if err != nil || counter == 0 {
			counter = 1
		} else {
			counter = counter.(int) + 1
		}

		// Store the new counter atomically
		ctx.Store().Set("counter", counter)

		id := nodeID + "-" + strconv.Itoa(counter)
		fmt.Printf("[%s] generating id %s\n", nodeID, id)

		resp := map[string]interface{}{
			"type":        "generate_ok",
			"in_reply_to": r.MsgID,
			"id":          id,
		}
		ctx.Reply(req.Src, resp)
	})

	node.Run()
}

func generateOK(nodeID string) maelstrom.Resp {
	return map[string]interface{}{
		"type":       "generate_ok",
		"in_reply_to": 0,
		"id":         nodeID + "-0",
	}
}

