package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"os"
	"strconv"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

func main() {
	node := maelstrom.NewNode()

	// Read init message and get our node ID
	initMsg := &maelstrom.InitMessageBody{}
	if err := json.Unmarshal([]byte(node.Stdin.(*os.File).Buf), initMsg); err != nil {
		log.Fatalf("failed to read init: %v", err)
	}

	// Store the node ID
	nodeID := initMsg.NodeID

	// Handle generate requests - need to maintain a counter per node for unique IDs
	node.Handle("generate", func(msg maelstrom.Message) error {
		var r struct {
			Type string `json:"type"`
			MsgID int64 `json:"msg_id"`
		}
		if err := json.Unmarshal([]byte(msg.Body), &r); err != nil {
			return fmt.Errorf("failed to unmarshal: %w", err)
		}

		// Use the stored node ID and increment counter
		counter := getAndIncrementCounter()
		id := nodeID + "-" + strconv.Itoa(counter)

		resp := map[string]interface{}{
			"type":        "generate_ok",
			"in_reply_to": r.MsgID,
			"id":          id,
		}

		msg.Body = marshal(resp)
		return nil
	})

	node.Init(initMsg.NodeID, initMsg.NodeIDs)
	node.Run()
}

func getAndIncrementCounter() int {
	// Read counter from file (stored by maelstrom in $MAELSTROM_NODE_STORE/counter)
	counterFile := os.Getenv("MAELSTROM_NODE_STORE") + "/counter"

	var counter int64 = 0

	if _, err := os.Stat(counterFile); err == nil {
		data, _ := os.ReadFile(counterFile)
		fmt.Printf("[DEBUG] reading counter file: %s\n", string(data))
		counter, _ = strconv.ParseInt(string(data), 10, 64)
	}

	counter++

	// Write back the incremented counter atomically
	os.WriteFile(counterFile, []byte(strconv.Itoa(int(counter))), 0644)

	return int(counter)
}

func marshal(v interface{}) []byte {
	data, _ := json.Marshal(v)
	return data
}

