package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"

	maelstrom "github.com/jepsen-io/maelstrom/demo/go"
)

func main() {
	node := maelstrom.NewNode()

	// Handle init message
	node.Handle("init", func(msg maelstrom.Message) error {
		var initMsg maelstrom.InitMessageBody
		if err := json.Unmarshal(msg.Body, &initMsg); err != nil {
			return fmt.Errorf("failed to unmarshal init: %w", err)
		}

		nodeID := initMsg.NodeID

		// Reply with the init OK
		initResp := map[string]interface{}{
			"type": "init_ok",
			"id":   nodeID,
		}

		msg.Body = marshal(initResp)
		return nil
	})

	// Handle generate requests using a linearizable KV store for counter management
	genKV := maelstrom.NewSeqKV(node)

	node.Handle("generate", func(msg maelstrom.Message) error {
		var r struct {
			Type      string `json:"type"`
			MsgID     int64  `json:"msg_id"`
			NodeID    string `json:"node_id"`
			GenNumber int64  `json:"gen_number"`
		}
		if err := json.Unmarshal(msg.Body, &r); err != nil {
			return fmt.Errorf("failed to unmarshal: %w", err)
		}

		nodeID := r.NodeID
		genNum := r.GenNumber

		// Read current counter from KV store
		var counter int64 = 0
		err := genKV.ReadInto(msg, "counter", &counter)
		if err != nil {
			return fmt.Errorf("failed to read counter: %w", err)
		}

		counter++

		// Update the counter in the KV store
		if updateErr := genKV.Write(msg, "counter", counter); updateErr != nil {
			return fmt.Errorf("failed to write counter: %w", updateErr)
		}

		id := nodeID + "-" + fmt.Sprintf("%d", counter)

		resp := map[string]interface{}{
			"type":        "generate_ok",
			"in_reply_to": msg.MsgID,
			"id":          id,
		}

		msg.Body = marshal(resp)
		return nil
	})

	node.Init(initMsg.NodeID, initMsg.NodeIDs)

	// Create a new KV client after node is initialized
	genKV := maelstrom.NewSeqKV(node)

	node.Run()
}

func marshal(v interface{}) []byte {
	data, _ := json.Marshal(v)
	return data
}

